/*
 * A045229  Numbers whose base-5 representation contains exactly three 1's and
 *          no 2's.
 * https://oeis.org/A045229
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 10, u16 n <= 46, u32 n <= 46, u64 n <= 46, u128 n <= 46,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by combinatorial unranking of base-5 digits with exactly
 * three 1's and no 2's. */
#include <stdint.h>

/* binomial coefficient C(n,k) for small n,k */
static uint64_t binom(unsigned n, unsigned k)
{
    if (k > n) return 0;
    if (k > n - k) k = n - k;
    uint64_t res = 1;
    for (unsigned i = 1; i <= k; ++i)
        res = res * (n - k + i) / i;
    return res;
}

/* 3^e,  e is small (e ≤ 20 for the problem range) */
static uint64_t pow3(unsigned e)
{
    uint64_t r = 1;
    for (unsigned i = 0; i < e; ++i) r *= 3;
    return r;
}

/* number of admissible numbers of a given base‑5 length */
static uint64_t count_len(unsigned len)
{
    if (len < 3) return 0;
    __int128 total = 0;

    /* first digit = 1 */
    if (len - 1 >= 2) {
        unsigned rem = len - 1 - 2;
        total += (__int128)binom(len - 1, 2) * (__int128)pow3(rem);
    }

    /* first digit = 3 or 4 */
    if (len - 1 >= 3) {
        unsigned rem = len - 1 - 3;
        total += 2 * (__int128)binom(len - 1, 3) * (__int128)pow3(rem);
    }

    if (total > (__int128)UINT64_MAX) return UINT64_MAX;
    return (uint64_t)total;
}

/* Map the ordinal n (starting at 1) to the corresponding number. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                 /* offset starts at 1 */

    /* locate the length that contains the nth element */
    unsigned len = 0;
    uint64_t cumulative = 0;
    while (1) {
        ++len;
        uint64_t c = count_len(len);
        if (cumulative + c >= n) break;
        cumulative += c;
    }

    /* rank within the numbers of this length, 1‑based */
    uint64_t rank = n - cumulative;

    seq_t value = 0;
    unsigned rem_ones = 3;

    for (unsigned pos = 0; pos < len; ++pos) {
        unsigned remaining_positions = len - pos - 1;

        const int *digits;
        unsigned dcount;
        if (pos == 0) {
            static const int digs0[3] = {1, 3, 4};
            digits = digs0; dcount = 3;
        } else {
            static const int digs1[4] = {0, 1, 3, 4};
            digits = digs1; dcount = 4;
        }

        for (unsigned di = 0; di < dcount; ++di) {
            unsigned d = digits[di];
            unsigned remaining_ones = rem_ones;
            if (d == 1) {
                if (remaining_ones == 0) continue;
                --remaining_ones;
            }
            if (remaining_ones > remaining_positions) continue;

            uint64_t ways = binom(remaining_positions, remaining_ones) *
                            pow3(remaining_positions - remaining_ones);

            if (rank > ways) {
                rank -= ways;
                continue;
            }

            /* choose this digit */
            value = value * 5 + d;
            rem_ones = remaining_ones;
            break;
        }
    }
    return value;
}
